062d\u062f\u060c \u0645\u0639 \u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u062b\u0628\u0627\u062a \u0627\u0644\u0648\u0631\u0643\u064a\u0646 \u0648\u0627\u0644\u0633\u0627\u0642\u064a\u0646.\n\u0627\u0631\u062c\u0639 \u0625\u0644\u0649 \u0627\u0644\u0645\u0631\u0643\u0632 \u0648\u0643\u0631\u0631 \u0627\u0644\u062a\u062f\u0648\u064a\u0631 \u0625\u0644\u0649 \u0627\u0644\u062c\u0627\u0646\u0628 \u0627\u0644\u0622\u062e\u0631.\n\u0642\u0645 \u0628\u062e\u0641\u0636 \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0639\u0644\u0648\u064a \u0645\u0646 \u062c\u0633\u0645\u0643 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629 \u0648\u0643\u0631\u0631 \u0630\u0644\u0643 \u0644\u0639\u062f\u062f \u0627\u0644\u062a\u0643\u0631\u0627\u0631\u0627\u062a \u0627\u0644\u0645\u0637\u0644\u0648\u0628\u0629.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1336","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"spine","secondary_muscles":["glutes","hamstrings"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/1336-WVD66ff.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/1336-WVD66ff.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"9750ce5f-1541-5880-8ed5-e55da7f1e7b3","source_id":"1744","name_en":"exercise ball dip","name_ar":"\u0645\u0645\u0627\u0631\u0633\u0629 \u062a\u0631\u0627\u062c\u0639 \u0627\u0644\u0643\u0631\u0629","match_names":["exercise ball dip"],"muscle":"triceps","equipment":"stability_ball","aliases":["exercise ball dip"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Sit on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.\nPlace your hands on the ball beside your hips, fingers pointing forward.\nEngage your triceps and push through your hands to lift your body off the ball, straightening your arms.\nLower your body back down by bending your elbows, keeping them close to your sides.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u062c\u0644\u0633 \u0639\u0644\u0649 \u0643\u0631\u0629 \u0627\u0644\u062b\u0628\u0627\u062a \u0645\u0639 \u0648\u0636\u0639 \u0642\u062f\u0645\u064a\u0643 \u0628\u0634\u0643\u0644 \u0645\u0633\u0637\u062d \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636 \u0648\u062b\u0646\u064a \u0631\u0643\u0628\u062a\u064a\u0643 \u0628\u0632\u0627\u0648\u064a\u0629 90 \u062f\u0631\u062c\u0629.\n\u0636\u0639 \u064a\u062f\u064a\u0643 \u0639\u0644\u0649 \u0627\u0644\u0643\u0631\u0629 \u0628\u062c\u0627\u0646\u0628 \u0648\u0631\u0643\u064a\u0643\u060c \u0645\u0639 \u062a\u0648\u062c\u064a\u0647 \u0623\u0635\u0627\u0628\u0639\u0643 \u0644\u0644\u0623\u0645\u0627\u0645.\n\u0642\u0645 \u0628\u062a\u0634\u063a\u064a\u0644 \u0627\u0644\u0639\u0636\u0644\u0629 \u062b\u0644\u0627\u062b\u064a\u0629 \u0627\u0644\u0631\u0624\u0648\u0633 \u0648\u0627\u062f\u0641\u0639 \u0628\u064a\u062f\u064a\u0643 \u0644\u0631\u0641\u0639 \u062c\u0633\u0645\u0643 \u0639\u0646 \u0627\u0644\u0643\u0631\u0629\u060c \u0645\u0639 \u0641\u0631\u062f \u0630\u0631\u0627\u0639\u064a\u0643.\n\u0642\u0645 \u0628\u062e\u0641\u0636 \u062c\u0633\u0645\u0643 \u0644\u0644\u0623\u0633\u0641\u0644 \u0639\u0646 \u0637\u0631\u064a\u0642 \u062b\u0646\u064a \u0645\u0631\u0641\u0642\u064a\u0643\u060c \u0648\u0625\u0628\u0642\u0627\u0626\u0647\u0645\u0627 \u0642\u0631\u064a\u0628\u064a\u0646 \u0645\u0646 \u062c\u0627\u0646\u0628\u064a\u0643.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1744","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"triceps","secondary_muscles":["chest","shoulders"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/1744-kprile3.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/1744-kprile3.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"42e0bbe7-9643-56a0-8376-73015ac1ea4d","source_id":"1559","name_en":"exercise ball hip flexor stretch","name_ar":"\u062a\u0645\u0631\u064a\u0646 \u062a\u0645\u062f\u062f \u0639\u0636\u0644\u0627\u062a \u0627\u0644\u0648\u0631\u0643 \u0639\u0644\u0649 \u0634\u0643\u0644 \u0643\u0631\u0629","match_names":["exercise ball hip flexor stretch"],"muscle":"glutes","equipment":"stability_ball","aliases":["exercise ball hip flexor stretch"],"logging_mode":"timed","load_convention":"external_total","guidance":{"steps_en":"Place the stability ball on the ground and kneel in front of it.\nPlace your right foot on top of the stability ball, with your knee bent at a 90-degree angle.\nExtend your left leg behind you, keeping it straight.\nLean forward, pushing your hips towards the stability ball, until you feel a stretch in your right hip flexor.\nHold the stretch for 20-30 seconds, then switch sides and repeat.","steps_ar":"\u0636\u0639 \u0643\u0631\u0629 \u0627\u0644\u062b\u0628\u0627\u062a \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636 \u0648\u0627\u0631\u0643\u0639 \u0623\u0645\u0627\u0645\u0647\u0627.\n\u0636\u0639 \u0642\u062f\u0645\u0643 \u0627\u0644\u064a\u0645\u0646\u0649 \u0641\u0648\u0642 \u0643\u0631\u0629 \u0627\u0644\u062b\u0628\u0627\u062a\u060c \u0645\u0639 \u062b\u0646\u064a \u0631\u0643\u0628\u062a\u0643 \u0628\u0632\u0627\u0648\u064a\u0629 90 \u062f\u0631\u062c\u0629.\n\u0645\u062f \u0633\u0627\u0642\u0643 \u0627\u0644\u064a\u0633\u0631\u0649 \u062e\u0644\u0641\u0643\u060c \u0645\u0639 \u0625\u0628\u0642\u0627\u0626\u0647\u0627 \u0645\u0633\u062a\u0642\u064a\u0645\u0629.\n\u0627\u0646\u062d\u0646\u0650 \u0625\u0644\u0649 \u0627\u0644\u0623\u0645\u0627\u0645\u060c \u0648\u0627\u062f\u0641\u0639 \u0648\u0631\u0643\u064a\u0643 \u0646\u062d\u0648 \u0643\u0631\u0629 \u0627\u0644\u062b\u0628\u0627\u062a\u060c \u062d\u062a\u0649 \u062a\u0634\u0639\u0631 \u0628\u062a\u0645\u062f\u062f \u0641\u064a \u062b\u0646\u064a\u0629 \u0627\u0644\u0648\u0631\u0643 \u0627\u0644\u064a\u0645\u0646\u0649.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u0627\u0644\u062a\u0645\u062f\u062f \u0644\u0645\u062f\u0629 20-30 \u062b\u0627\u0646\u064a\u0629\u060c \u062b\u0645 \u0628\u062f\u0644 \u0627\u0644\u062c\u0648\u0627\u0646\u0628 \u0648\u0643\u0631\u0631 \u0627\u0644\u0623\u0645\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1559","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"glutes","secondary_muscles":["quadriceps","hamstrings"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/1559-2LQkNPW.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/1559-2LQkNPW.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"dd658e35-c174-5f4a-83dc-9c0b0e27c80c","source_id":"1338","name_en":"exercise ball hug","name_ar":"\u0645\u0645\u0627\u0631\u0633\u0629 \u0639\u0646\u0627\u0642 \u0627\u0644\u0643\u0631\u0629","match_names":["exercise ball hug"],"muscle":"back","equipment":"stability_ball","aliases":["exercise ball hug"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Sit on the stability ball with your feet flat on the ground and your back straight.\nHold the stability ball with both hands, hugging it close to your chest.\nEngage your core muscles and slowly lean back, keeping your back straight and your feet planted on the ground.\nContinue leaning back until you feel a stretch in your back muscles.\nHold the position for a few seconds, then slowly return to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u062c\u0644\u0633 \u0639\u0644\u0649 \u0643\u0631\u0629 \u0627\u0644\u062b\u0628\u0627\u062a \u0645\u0639 \u0648\u0636\u0639 \u0642\u062f\u0645\u064a\u0643 \u0628\u0634\u0643\u0644 \u0645\u0633\u0637\u062d \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636 \u0648\u0638\u0647\u0631\u0643 \u0645\u0633\u062a\u0642\u064a\u0645\u064b\u0627.\n\u0623\u0645\u0633\u0643 \u0643\u0631\u0629 \u0627\u0644\u062b\u0628\u0627\u062a \u0628\u0643\u0644\u062a\u0627 \u064a\u062f\u064a\u0643\u060c \u0648\u0627\u062d\u062a\u0636\u0646\u0647\u0627 \u0628\u0627\u0644\u0642\u0631\u0628 \u0645\u0646 \u0635\u062f\u0631\u0643.\n\u0642\u0645 \u0628\u062a\u0634\u063a\u064a\u0644 \u0639\u0636\u0644\u0627\u062a\u0643 \u0627\u0644\u0623\u0633\u0627\u0633\u064a\u0629 \u0648\u0627\u0646\u062d\u0646\u064a \u0644\u0644\u062e\u0644\u0641 \u0628\u0628\u063