0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"2741","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"biceps","secondary_muscles":["forearms"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/2741-OVTZ65k.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/2741-OVTZ65k.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"8ac8a0e2-d211-51a1-8f78-fa04240e7957","source_id":"2133","name_en":"farmers walk","name_ar":"\u0627\u0644\u0645\u0632\u0627\u0631\u0639\u0648\u0646 \u064a\u0633\u064a\u0631\u0648\u0646","match_names":["farmers walk"],"muscle":"quads","equipment":"dumbbell","aliases":["farmers walk"],"logging_mode":"weighted_reps","load_convention":"per_hand","guidance":{"steps_en":"Stand up straight with a dumbbell in each hand, palms facing your sides.\nKeep your back straight and your shoulders back.\nTake small, controlled steps forward, maintaining an upright posture.\nContinue walking for the desired distance or time.\nTo finish, stop walking and carefully lower the dumbbells to your sides.","steps_ar":"\u0642\u0641 \u0628\u0634\u0643\u0644 \u0645\u0633\u062a\u0642\u064a\u0645 \u0645\u0639 \u062d\u0645\u0644 \u0627\u0644\u062f\u0645\u0628\u0644 \u0641\u064a \u0643\u0644 \u064a\u062f\u060c \u0645\u0639 \u062a\u0648\u062c\u064a\u0647 \u0631\u0627\u062d\u062a\u064a \u0627\u0644\u064a\u062f\u064a\u0646 \u0625\u0644\u0649 \u062c\u0627\u0646\u0628\u064a\u0643.\n\u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u0627\u0633\u062a\u0642\u0627\u0645\u0629 \u0638\u0647\u0631\u0643 \u0648\u0643\u062a\u0641\u064a\u0643 \u0625\u0644\u0649 \u0627\u0644\u062e\u0644\u0641.\n\u0627\u062a\u062e\u0630 \u062e\u0637\u0648\u0627\u062a \u0635\u063a\u064a\u0631\u0629 \u0648\u0645\u0646\u0636\u0628\u0637\u0629 \u0644\u0644\u0623\u0645\u0627\u0645\u060c \u0648\u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u0648\u0636\u0639\u064a\u0629 \u0645\u0633\u062a\u0642\u064a\u0645\u0629.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u0627\u0644\u0645\u0634\u064a \u0644\u0644\u0645\u0633\u0627\u0641\u0629 \u0623\u0648 \u0627\u0644\u0648\u0642\u062a \u0627\u0644\u0645\u0637\u0644\u0648\u0628.\n\u0644\u0625\u0646\u0647\u0627\u0621 \u0627\u0644\u062a\u0645\u0631\u064a\u0646\u060c \u062a\u0648\u0642\u0641 \u0639\u0646 \u0627\u0644\u0645\u0634\u064a \u0648\u0642\u0645 \u0628\u062e\u0641\u0636 \u0627\u0644\u062f\u0645\u0628\u0644\u0632 \u0628\u0639\u0646\u0627\u064a\u0629 \u0639\u0644\u0649 \u062c\u0627\u0646\u0628\u064a\u0643.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"2133","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"quads","secondary_muscles":["calves","forearms","core"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/2133-qPEzJjA.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/2133-qPEzJjA.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"9ff79c07-d2b7-5cea-8004-767a369ad29c","source_id":"0455","name_en":"finger curls","name_ar":"\u062a\u062c\u0639\u064a\u062f \u0627\u0644\u0627\u0635\u0628\u0639","match_names":["finger curls"],"muscle":"forearms","equipment":"barbell","aliases":["finger curls"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Sit on a bench with your feet flat on the ground and hold a barbell with an underhand grip, palms facing up.\nRest your forearms on your thighs, allowing your wrists to hang off the edge.\nSlowly curl your fingers towards your palms, squeezing the barbell tightly.\nHold the contraction for a moment, then slowly release your fingers back to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u062c\u0644\u0633 \u0639\u0644\u0649 \u0645\u0642\u0639\u062f \u0645\u0639 \u0648\u0636\u0639 \u0642\u062f\u0645\u064a\u0643 \u0628\u0634\u0643\u0644 \u0645\u0633\u0637\u062d \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636\u060c \u0648\u0627\u0645\u0633\u0643 \u0628\u0627\u0644\u062d\u062f\u064a\u062f \u0628\u0642\u0628\u0636\u0629 \u0633\u0641\u0644\u064a\u0629\u060c \u0645\u0639 \u062a\u0648\u062c\u064a\u0647 \u0631\u0627\u062d\u062a\u064a \u0627\u0644\u064a\u062f\u064a\u0646 \u0644\u0644\u0623\u0639\u0644\u0649.\n\u0636\u0639 \u0633\u0627\u0639\u062f\u064a\u0643 \u0639\u0644\u0649 \u0641\u062e\u0630\u064a\u0643\u060c \u0645\u0639 \u0627\u0644\u0633\u0645\u0627\u062d \u0644\u0645\u0639\u0635\u0645\u064a\u0643 \u0628\u0627\u0644\u062a\u062f\u0644\u064a \u0645\u0646 \u0627\u0644\u062d\u0627\u0641\u0629.\n\u0642\u0645 \u0628\u062a\u062d\u0631\u064a\u0643 \u0623\u0635\u0627\u0628\u0639\u0643 \u0628\u0628\u0637\u0621 \u0646\u062d\u0648 \u0631\u0627\u062d\u0629 \u064a\u062f\u0643\u060c \u0645\u0639 \u0627\u0644\u0636\u063a\u0637 \u0639\u0644\u0649 \u0627\u0644\u062d\u062f\u064a\u062f \u0628\u0625\u062d\u0643\u0627\u0645.\n\u0627\u0633\u062a\u0645\